begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into auth.users(id) select ('4d000000-0000-4000-8000-00000000000'||n)::uuid from generate_series(1,4)n;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) select id,id,'totp','verified',now(),now() from auth.users where id::text like '4d000000-%';
insert into auth.sessions(id,user_id,factor_id,aal) select id,id,id,'aal2' from auth.users where id::text like '4d000000-%';
insert into public.team_profiles(id,full_name) select id,'Synthetic dispatch staff' from auth.users where id::text like '4d000000-%' and id::text not like '%4';
insert into public.team_role_assignments select ('4d000000-0000-4000-8000-00000000000'||v.n)::uuid,r.id from (values(1,'operations_lead'),(2,'content_community_lead'),(3,'technical_lead'))v(n,code)join public.roles r on r.code=v.code;
insert into public.services(id,slug,title,description,status,accepting_requests)values('4d100000-0000-4000-8000-000000000001','delivery-fixture','Synthetic service','Test','published',true);
insert into business_private.project_requests(id,service_id,service_snapshot,full_name,email,whatsapp,requirements,consent_version,idempotency_hash,payload_hash)values('4d200000-0000-4000-8000-000000000001','4d100000-0000-4000-8000-000000000001','{"title":"Synthetic service"}','Synthetic Client','delivery@example.invalid','+237600000000','A synthetic delivery request','test',decode(repeat('4d',32),'hex'),decode(repeat('4e',32),'hex'));
insert into business_private.quotations(id,request_id)values('4d300000-0000-4000-8000-000000000001','4d200000-0000-4000-8000-000000000001');
create function pg_temp.content() returns jsonb language sql as $$select jsonb_build_object('projectDescription','Test project','scope','Scope','deliverables','Deliverables','timeline','Two weeks','paymentTerms','Explicit terms','validUntil',(current_date+30)::text,'notes','','exclusions','','teamAgreement',true,'currency','XAF','items',jsonb_build_array(jsonb_build_object('description','Implementation','quantity',1,'unitAmount',50000)))$$;
insert into business_private.quotation_revisions(id,quotation_id,revision,state,client_snapshot,request_snapshot,content,pdf_sha256,finalized_at,template_version)values('4d400000-0000-4000-8000-000000000001','4d300000-0000-4000-8000-000000000001',1,'finalized','{"name":"Synthetic Client","email":"delivery@example.invalid","whatsapp":"+237600000000"}','{"reference":"TEST","service":"Synthetic service"}',pg_temp.content(),repeat('a',64),now(),1);
create function pg_temp.claims(n integer,aal text default 'aal2') returns text language sql as $$select json_build_object('sub','4d000000-0000-4000-8000-00000000000'||n,'role','authenticated','aal',aal,'session_id','4d000000-0000-4000-8000-00000000000'||n,'exp',extract(epoch from now()+interval '1 hour')::bigint)::text$$;
create temporary table targets(channel text,id uuid);grant all on targets to authenticated;
select extensions.is((select count(*) from public.permissions),27::bigint,'reviewed current permission catalog');
select extensions.is((select count(*) from public.role_permissions),52::bigint,'reviewed current role mappings');
select extensions.ok(not has_function_privilege('anon','public.prepare_quotation_delivery(uuid,text)','execute'),'anonymous cannot prepare dispatch');
select extensions.ok(not has_function_privilege('service_role','public.record_quotation_dispatch(uuid,integer,uuid,text,text,boolean)','execute'),'ingress secret cannot record dispatch');
select extensions.ok(not has_table_privilege('authenticated','business_private.quotation_deliveries','INSERT,UPDATE,DELETE'),'no ordinary direct dispatch mutation');
set local role authenticated;
select set_config('request.jwt.claims',pg_temp.claims(1,'aal1'),true);
select extensions.throws_ok($$select public.prepare_quotation_delivery('4d400000-0000-4000-8000-000000000001','whatsapp')$$,'42501',null,'AAL1 denied');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
select extensions.throws_ok($$select public.prepare_quotation_delivery('4d400000-0000-4000-8000-000000000001','whatsapp')$$,'42501',null,'Content denied');
select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.throws_ok($$select public.list_quotation_deliveries('4d200000-0000-4000-8000-000000000001')$$,'42501',null,'Technology denied');
select set_config('request.jwt.claims',pg_temp.claims(4),true);
select extensions.throws_ok($$select public.prepare_quotation_delivery('4d400000-0000-4000-8000-000000000001','email')$$,'42501',null,'unassigned AAL2 denied');
select set_config('request.jwt.claims',pg_temp.claims(1),true);
select extensions.throws_ok($$select public.prepare_quotation_delivery('4d400000-0000-4000-8000-000000000001','sms')$$,'22023',null,'unapproved channel rejected');
insert into targets select 'whatsapp',(public.prepare_quotation_delivery('4d400000-0000-4000-8000-000000000001','whatsapp')->>'id')::uuid;
select extensions.is(public.get_quotation_delivery((select id from targets where channel='whatsapp'))->>'recipient','+237600000000','phone selected from exact linked request');
select extensions.is((public.prepare_quotation_delivery('4d400000-0000-4000-8000-000000000001','whatsapp')->>'id')::uuid,(select id from targets where channel='whatsapp'),'repeat preparation returns same record');
select extensions.is(jsonb_array_length(public.get_quotation_delivery((select id from targets where channel='whatsapp'))->'events'),1,'repeat preparation creates no extra event');
insert into targets select 'email',(public.prepare_quotation_delivery('4d400000-0000-4000-8000-000000000001','email')->>'id')::uuid;
select extensions.is(public.get_quotation_delivery((select id from targets where channel='email'))->>'recipient','delivery@example.invalid','email selected from exact linked request');
select extensions.is(public.get_quotation_delivery((select id from targets where channel='email'))->>'recipient_source','submitted','no fabricated verification claim');
select extensions.throws_ok($$select public.record_quotation_dispatch((select id from targets where channel='whatsapp'),1,'4d500000-0000-4000-8000-000000000001','MANUALLY_SENT','',false)$$,'22023',null,'explicit staff attestation required');
select extensions.throws_ok($$select public.record_quotation_dispatch((select id from targets where channel='whatsapp'),null,'4d500000-0000-4000-8000-000000000001','MANUALLY_SENT','',true)$$,'22023',null,'null version denied');
select extensions.lives_ok($$select public.record_quotation_dispatch((select id from targets where channel='whatsapp'),1,'4d500000-0000-4000-8000-000000000001','MANUALLY_SENT','Synthetic handoff',true)$$,'manual dispatch accepted');
select extensions.is(public.get_quotation_delivery((select id from targets where channel='whatsapp'))->>'status','MANUALLY_SENT','staff dispatch status only');
select extensions.ok(public.get_quotation_delivery((select id from targets where channel='whatsapp'))->>'confirmed_at' is not null,'timestamp recorded server-side');
select extensions.lives_ok($$select public.record_quotation_dispatch((select id from targets where channel='whatsapp'),1,'4d500000-0000-4000-8000-000000000001','MANUALLY_SENT','Synthetic handoff',true)$$,'same confirmation key is idempotent');
select extensions.is(jsonb_array_length(public.get_quotation_delivery((select id from targets where channel='whatsapp'))->'events'),2,'duplicate confirmation adds no event');
select extensions.throws_ok($$select public.record_quotation_dispatch((select id from targets where channel='whatsapp'),2,'4d500000-0000-4000-8000-000000000002','MANUALLY_SENT','Again',true)$$,'PT409',null,'new key cannot confirm terminal dispatch twice');
select extensions.throws_ok($$select public.record_quotation_dispatch((select id from targets where channel='whatsapp'),1,'4d500000-0000-4000-8000-000000000001','NEEDS_FOLLOW_UP','Different payload',false)$$,'PT409',null,'same key cannot change confirmation payload');
select extensions.lives_ok($$select public.record_quotation_dispatch((select id from targets where channel='email'),1,'4d500000-0000-4000-8000-000000000003','NEEDS_FOLLOW_UP','Needs attention',false)$$,'failed preparation can be flagged without delivery claim');
reset role;
create function pg_temp.reject_dispatch_audit()returns trigger language plpgsql as $$begin if new.action='quotation.dispatch_recorded' then raise exception 'Synthetic audit failure';end if;return new;end;$$;
create trigger reject_dispatch_audit before insert on public.audit_logs for each row execute function pg_temp.reject_dispatch_audit();
set local role authenticated;
select extensions.throws_ok($$select public.record_quotation_dispatch((select id from targets where channel='email'),2,'4d500000-0000-4000-8000-000000000004','MANUALLY_SENT','',true)$$,'P0001',null,'audit failure rolls back status and event');
select extensions.is(public.get_quotation_delivery((select id from targets where channel='email'))->>'status','NEEDS_FOLLOW_UP','failed confirmation state unchanged');
select extensions.is(jsonb_array_length(public.get_quotation_delivery((select id from targets where channel='email'))->'events'),2,'failed confirmation event rolled back');
reset role;drop trigger reject_dispatch_audit on public.audit_logs;
select extensions.is((select count(*) from public.audit_logs where resource_type='quotation_delivery' and resource_id=(select id::text from targets where channel='whatsapp') and action='quotation.dispatch_recorded'),1::bigint,'one manual confirmation audit');
select extensions.throws_ok($$update business_private.quotation_deliveries set recipient='other@example.invalid' where id=(select id from targets where channel='email')$$,'42501',null,'dispatch recipient is immutable');
select extensions.throws_ok($$delete from business_private.quotation_delivery_events where delivery_id=(select id from targets where channel='email')$$,'42501',null,'event history is append-only');
update business_private.project_requests set email='changed@example.invalid' where id='4d200000-0000-4000-8000-000000000001';
set local role authenticated;
select extensions.throws_ok($$select public.get_quotation_delivery((select id from targets where channel='email'))$$,'22023',null,'contact drift blocks preparation instead of silently switching recipients');
select set_config('request.jwt.claims',pg_temp.claims(1,'aal1'),true);
select extensions.is((select count(*) from business_private.quotation_deliveries),0::bigint,'direct AAL1 RLS hides dispatch records');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
select extensions.is((select count(*) from business_private.quotation_delivery_events),0::bigint,'direct Content RLS hides dispatch events');
reset role;
update public.team_profiles set is_active=false where id='4d000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims',pg_temp.claims(1),true);
select extensions.throws_ok($$select public.list_quotation_deliveries('4d200000-0000-4000-8000-000000000001')$$,'42501',null,'inactive staff denied');
reset role;
select * from extensions.finish();rollback;
